package pro.megadedh.fooddelivery.features.main.ui.screens.dishesimport android.app.Dialogimport android.os.Bundleimport android.widget.Buttonimport android.widget.ImageViewimport android.widget.TextViewimport androidx.fragment.app.DialogFragmentimport androidx.fragment.app.FragmentManagerimport coil.loadimport com.google.android.material.dialog.MaterialAlertDialogBuilderimport pro.megadedh.core.ui.utils.argsimport pro.megadedh.common.api.presentation.model.result.Dishimport pro.megadedh.fooddelivery.features.main.ui.Rimport pro.megadedh.fooddelivery.common.ui.R as CommonRclass DishDialog : DialogFragment() {    private var dish by args<Dish>()    private var basketContainsDish by args<Boolean>()    private lateinit var listener: ClickDialogListener    interface ClickDialogListener {        fun onDialogAddDishClick(dish: Dish)    }    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog {        setupListeners()        val dialog = MaterialAlertDialogBuilder(requireContext())        val view = layoutInflater.inflate(R.layout.dialog_dish, null)        val addButton = view.findViewById<Button>(R.id.btnAddDish)        val dishAlreadyInCart = getString(R.string.dish_already_in_cart)        view.findViewById<ImageView>(R.id.btnClose)?.setOnClickListener {            dismiss()        }        view.findViewById<TextView>(R.id.tvPrice).text = getString(            CommonR.string.dish_dialog_price_template,            dish.price,        )        view.findViewById<TextView>(R.id.tvWeight).text = getString(            CommonR.string.dish_dialog_weight_template,            dish.weight,        )        view.findViewById<TextView>(R.id.tvDishName).text = dish.name        view.findViewById<TextView>(R.id.tvDishDescription).text = dish.description        view.findViewById<ImageView>(R.id.ivDialogDish).load(dish.imageUrl)        if (basketContainsDish) {            addButton.text = dishAlreadyInCart        } else {            addButton.setOnClickListener {                listener.onDialogAddDishClick(dish)                it.setOnClickListener(null)                addButton.text = dishAlreadyInCart            }        }        return dialog.setView(view)            .create()    }    private fun setupListeners() {        try {            listener = requireParentFragment() as ClickDialogListener        } catch (e: ClassCastException) {            throw ClassCastException(                (context.toString() +                        " must implement ClickDialogListener")            )        }    }    companion object {        fun show(            fragmentManager: FragmentManager,            dish: Dish,            basketContainsDish: Boolean        ) = DishDialog().apply {            this.dish = dish            this.basketContainsDish = basketContainsDish            this.show(fragmentManager, "DishDialog")        }    }}